<span class="line"><span style="color:#ABB2BF;">    x3 </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> rng.</span><span style="color:#61AFEF;">randn</span><span style="color:#ABB2BF;">(n_samples)</span></span>
